const D = { energy:.6, scale:1, density:.5, speed:1, hue:44, x:.5, y:.55, netting:.45, style:'galvanised', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), paper = (sty === 'engraving'), rust = (sty === 'rust'), dk = (sty === 'chiaroscuro');
// a SET composites OVER a bg: alpha scales every mark. Never paint a black veil.
const AL = cl(P.alpha, 0, 100);
if (AL > 0.5) {

const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.44 + .56*P.energy) * (.55 + .5*K.intensity) + bsm*.24;

const dA = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dB = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9) + .20*Math.sin(K.t*2.29+2.6);
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

const BAY = u*.46;                                  // standard bay, FIXED
const LIFT = u*.34*P.scale;                         // lift (storey) height
const TUB = u*.011*P.scale;                         // tube radius
const NX = 3 + Math.round(cl(P.density,0,1)*3);     // bays across
const NY = 2 + Math.round(cl(P.density,0,1)*3);     // lifts up
const NZ = 2;                                       // rows of standards (inner + outer)
const DZ = u*.30*P.scale;                           // distance between the two rows

// the scaffold stands still; the CAMERA breathes — real parallax, no beat flash
const camX = (NX-1)*BAY*.5 + u*.075*dA*P.energy;
const camY = -(NY*LIFT*.42) + u*.05*dB*P.energy;
const camZ = -u*(1.30 + .10*P.scale) + u*.085*dC*P.energy;
const yaw = .10 + .035*dA*P.energy + .022*Math.sin(K.t*.113+1.7);
const ca = Math.cos(yaw), sa = Math.sin(yaw);
const f = u*1.05, NEAR = u*.06;
const vcx = cl(P.x,.1,.9)*width, vcy = cl(P.y,.25,.85)*height;

// the sun crawls the facade; a hoist creeps up and down its own slow clock
const sunA = .90*Math.sin(K.t*.041*P.speed) + .36*Math.sin(K.t*.101*P.speed+2.0);
const hoistY = -(NY*LIFT)*(.16 + .40*(.5 + .5*Math.sin(K.t*.083*P.speed + 1.2)))
             - (NY*LIFT)*.10*Math.sin(K.t*.191*P.speed);

const AXa = new Float64Array(12), AYa = new Float64Array(12), AZa = new Float64Array(12);
const BXa = new Float64Array(18), BYa = new Float64Array(18);
function poly(v){
  const n = v.length/3;
  for (let i=0;i<n;i++){
    const X = v[i*3]-camX, Y = v[i*3+1]-camY, Z = v[i*3+2]-camZ;
    AXa[i] = X*ca - Z*sa; AYa[i] = Y; AZa[i] = X*sa + Z*ca;
  }
  let m = 0;
  for (let i=0;i<n;i++){
    const j = (i+1)%n, az = AZa[i], bz = AZa[j], ai = az>NEAR, bi2 = bz>NEAR;
    if (ai){ BXa[m] = vcx + f*AXa[i]/az; BYa[m] = vcy + f*AYa[i]/az; m++; }
    if (ai !== bi2){
      const tt = (NEAR-az)/(bz-az);
      BXa[m] = vcx + f*(AXa[i]+(AXa[j]-AXa[i])*tt)/NEAR;
      BYa[m] = vcy + f*(AYa[i]+(AYa[j]-AYa[i])*tt)/NEAR; m++;
    }
  }
  if (m < 3) return false;
  beginShape(); for (let i=0;i<m;i++) vertex(BXa[i], BYa[i]); endShape(CLOSE);
  return true;
}
function pt2(X,Y,Z){
  const dx = X-camX, dy = Y-camY, dz = Z-camZ;
  const rz = dx*sa + dz*ca;
  if (rz <= NEAR) return null;
  return [vcx + f*(dx*ca - dz*sa)/rz, vcy + f*dy/rz, rz];
}

function mixc(c,d,t){ const dh = ((d[0]-c[0])%360+540)%360-180;
  return [c[0]+dh*t, c[1]+(d[1]-c[1])*t, c[2]+(d[2]-c[2])*t]; }
const HAZE = paper ? [40, 6, 90] : wire ? [212, 58, 22] : dk ? [HU, 12, 8]
           : rust ? [18, 40, 26] : [(HU+180)%360, 12, 34];
const fogA = (paper||wire) ? .24 : .50;
function tone(v, tv){
  if (paper) return [40, 5 + 4*tv, cl(96 - 56*(1-v), 34, 96)];
  if (wire)  return [212, 60, cl(12 + 12*v, 8, 34)];
  if (dk)    return [HU, cl(22 - 12*v, 0, 26), cl(2 + 90*Math.pow(v,1.9), 1, 96)];
  if (rust)  return [cl(15 + 18*tv - 4*v, 2, 40), cl(32 + 32*tv - 12*v, 5, 66), cl(7 + 74*v, 4, 92)];
  return [(HU + 170 - 8*v + 8*tv + 360)%360, cl(9 - 5*v + 6*tv, 0, 16), cl(12 + 76*v, 5, 95)];
}
function ink(a){
  if (wire) stroke(190, 30, 100, a*AL/100);
  else if (paper) stroke(30, 20, 14, a*AL/100);
  else stroke((HU+170)%360, 8, 78, a*.26*AL/100);
}
function fl2(c, a){ fill(c[0], c[1], c[2], (a===undefined?100:a)*AL/100); }

// a tube: an axis-aligned run drawn as a shaded bar. Verticals stay vertical under
// pure yaw, so standards are exact rects; ledgers/transoms go through poly().
function tubeV(X, Z, y0, y1, tv, lam){
  const p = pt2(X, (y0+y1)*.5, Z);
  if (!p) return;
  const rw = f*TUB/p[2];
  if (rw < .35) return;
  const ya = vcy + f*(y0 - camY)/p[2], yb = vcy + f*(y1 - camY)/p[2];
  const hz = cl((p[2] - NEAR)/(u*3.2), 0, 1);
  const NS = cl(Math.round(rw/1.6), 1, 4);
  for (let s2=0; s2<NS; s2++){
    const q0 = -1 + 2*s2/NS, q1 = -1 + 2*(s2+1)/NS, qm = (q0+q1)*.5;
    const v = cl((.18 + .82*Math.cos((qm - lam*.7)*1.35)) * (.42+.5*gl) * (.9+.2*tv), 0, 1);
    const c = mixc(tone(v, tv), HAZE, hz*fogA);
    if (wire){ noFill(); ink(46); } else { noStroke(); fl2(c); }
    rect(p[0] + q0*rw, Math.min(ya,yb), (q1-q0)*rw + .9, Math.abs(yb-ya));
  }
}
function tubeH(x0,y0,z0, x1,y1,z1, tv, lam){
  const v = cl((.20 + .74*Math.cos((lam - .25)*1.1)) * (.42+.5*gl) * (.9+.2*tv), 0, 1);
  const pm = pt2((x0+x1)*.5, (y0+y1)*.5, (z0+z1)*.5);
  const hz = pm ? cl((pm[2] - NEAR)/(u*3.2), 0, 1) : .5;
  const c = mixc(tone(v, tv), HAZE, hz*fogA);
  if (wire){ noFill(); ink(46); } else { noStroke(); fl2(c); }
  poly([x0, y0-TUB, z0, x1, y1-TUB, z1, x1, y1+TUB, z1, x0, y0+TUB, z0]);
}

strokeWeight(Math.max(1, u*.0013));
const lamF = cl(.5 + .5*sunA, 0, 1);

// ---- the frame: standards (vertical), ledgers (horizontal), transoms, braces -------
for (let zi=NZ-1; zi>=0; zi--){                        // far row first
  const Z = zi ? 0 : -DZ;                              // inner row at 0, outer at -DZ
  for (let bx2=0; bx2<NX; bx2++){
    const X = bx2*BAY;
    const tv = fr(bx2*31.7 + zi*13.3);
    // standard, full height
    tubeV(X, Z, -NY*LIFT - LIFT*.22, 0, tv, lamF*2-1);
    // ledgers + transoms + guardrails at every lift
    for (let ly=0; ly<=NY; ly++){
      const Y = -ly*LIFT;
      if (bx2 < NX-1) tubeH(X, Y, Z, X+BAY, Y, Z, fr(bx2*7.1+ly*3.3), lamF);
      if (zi === 0 && bx2 < NX-1 && ly < NY) tubeH(X, Y-LIFT*.47, Z, X+BAY, Y-LIFT*.47, Z, fr(bx2*5.9+ly*2.1), lamF);
      if (zi === 0) tubeH(X, Y, -DZ, X, Y, 0, fr(bx2*11.3+ly*4.7), lamF*.6);   // transom, ties the rows
    }
    // a facade brace on some bays — the diagonal that makes it read as scaffold
    if (zi === 0 && bx2 < NX-1 && fr(bx2*23.1) < .55){
      const ly = Math.floor(fr(bx2*29.3)*NY);
      const up = fr(bx2*3.7) < .5;
      tubeH(X, -ly*LIFT - (up?0:LIFT), Z, X+BAY, -ly*LIFT - (up?LIFT:0), Z, .5, lamF*.8);
    }
  }
  // ---- boards: the working platform on each lift, seen edge-on and from below
  if (zi === 0){
    for (let ly=1; ly<=NY; ly++){
      const Y = -ly*LIFT;
      const below = (Y > camY);
      const pv = (below ? .30 : .10) * (.5+.55*gl) + .05;
      for (let bd=0; bd<4; bd++){
        const zz = -DZ + (DZ)*(bd+.5)/4;
        const c = mixc(tone(cl(pv*(.86 + .26*fr(ly*7.7 + bd*3.1)), 0, 1), fr(ly*2.3+bd)), HAZE, .34*fogA);
        if (wire){ noFill(); ink(38); } else { noStroke(); fl2(c); }
        poly([-BAY*.10, Y, zz, (NX-1)*BAY + BAY*.10, Y, zz,
              (NX-1)*BAY + BAY*.10, Y, zz + DZ*.21, -BAY*.10, Y, zz + DZ*.21]);
      }
      // toe board
      const c2 = mixc(tone(cl(.16*(.5+.55*gl)+.05, 0, 1), .5), HAZE, .34*fogA);
      if (!wire){ noStroke(); fl2(c2); }
      poly([-BAY*.10, Y, -DZ, (NX-1)*BAY + BAY*.10, Y, -DZ,
            (NX-1)*BAY + BAY*.10, Y - LIFT*.09, -DZ, -BAY*.10, Y - LIFT*.09, -DZ]);
    }
  }
}

// ---- debris netting on the OUTER row: translucent, so the bg still reads through --
const NET = cl(P.netting, 0, 1);
if (NET > .02 && !wire){
  for (let bx2=0; bx2<NX-1; bx2++){
    for (let ly=0; ly<NY; ly++){
      if (fr(bx2*17.7 + ly*5.3) > NET) continue;
      const x0 = bx2*BAY, x1 = (bx2+1)*BAY;
      const y0 = -(ly+1)*LIFT, y1 = -ly*LIFT;
      const sag = LIFT*.06*Math.sin(K.t*(.5 + fr(bx2*3.1+ly)*.5) + bx2*1.7 + ly*.9);
      const nv = cl((.30 + .34*lamF) * (.5+.5*gl), 0, 1);
      const c = mixc(tone(nv, fr(bx2*2.3+ly*7.1)), HAZE, .3*fogA);
      noStroke();
      fl2(paper ? [40, 8, 84] : dk ? [HU, 16, 30] : [(HU+2)%360, cl(38 + 16*fr(bx2*11.3), 0, 70), c[2]], 34);
      poly([x0, y0 + sag, -DZ*1.14, x1, y0 - sag, -DZ*1.14, x1, y1 - sag*.6, -DZ*1.14, x0, y1 + sag*.6, -DZ*1.14]);
    }
  }
}

// ---- the hoist: a gin wheel and a load creeping the face on its own slow clock -----
if (!wire){
  const hx = (NX-1)*BAY*.72;
  const p = pt2(hx, hoistY, -DZ*1.25);
  const pTop = pt2(hx, -NY*LIFT - LIFT*.18, -DZ*1.25);
  if (p && pTop){
    ink(paper ? 46 : 40); strokeWeight(Math.max(1, u*.0016));
    line(pTop[0], pTop[1], p[0], p[1]);
    const rw = Math.max(1.5, f*(u*.028*P.scale)/p[2]);
    const c = mixc(tone(cl(.34*(.5+.55*gl)+.06, 0, 1), .4), HAZE, .3*fogA);
    noStroke(); fl2(c);
    rect(p[0] - rw, p[1], rw*2, rw*1.5);
  }
}

// ---- sun catching the tube tops (partial frame, ADD, low alpha) ---------------------
if (!paper && !wire && AL > 8){
  push(); blendMode(ADD); noStroke();
  for (let ly=0; ly<=NY; ly++){
    const Y = -ly*LIFT;
    const lz = cl(.2 + .8*Math.exp(-Math.pow(ly - (NY*(.5+.45*Math.sin(K.t*.067*P.speed))), 2)*.5), 0, 1);
    fill(dk?HU:(HU+2)%360, dk?10:24, 100, cl((1.6 + 3.6*gl*lz*lamF)*AL/100, 0, 12));
    poly([-BAY*.10, Y - TUB*3, -DZ, (NX-1)*BAY + BAY*.10, Y - TUB*3, -DZ,
          (NX-1)*BAY + BAY*.10, Y + TUB*3, -DZ, -BAY*.10, Y + TUB*3, -DZ]);
  }
  pop(); blendMode(BLEND);
}
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
}
